#include "../Core/CoreCoordinator.hpp"
#include <iostream>
#include <stdexcept>
#include <array>
using namespace xone;
using namespace xone::l01;
static int count=0;
static void ok(bool cond,const char* name){if(!cond)throw std::runtime_error(name);}
static void scenario(const char* name,void(*f)()){f();++count;std::cout<<"PASS "<<name<<'\n';}
static SurfaceResult edge(int ctrl,int phase){return {SurfaceKind::Edge,ctrl,phase,12,phase?127:0};}
static SurfaceResult dj(int cc,int v){return {SurfaceKind::Dj,-1,0,cc,v};}
static SurfaceResult cc(int c,int v){return {SurfaceKind::Cc,-1,0,c,v};}
static bool find(const GestureBatch& b,GestureEventKind kind,int role,int phase){for(std::size_t i=0;i<b.count;++i){auto e=b.items[i];if(e.kind==kind&&(kind!=GestureEventKind::Qualified||(e.role==role&&static_cast<int>(e.phase)==phase)))return true;}return false;}
int main(){try {
scenario("S2-LONG-199-200",[](){GestureS2 g;GestureBatch b;ok(g.accept(edge(1,1),1000,b),"down");b={};g.onTimer(1089,b);ok(b.count==0,"89");b={};g.onTimer(1090,b);ok(find(b,GestureEventKind::Qualified,1,4),"90 SHIFT");b={};g.onTimer(1199,b);ok(b.count==0,"199 no long");b={};g.onTimer(1200,b);ok(find(b,GestureEventKind::Qualified,1,1),"200 long");b={};g.accept(edge(1,0),1201,b);ok(find(b,GestureEventKind::Qualified,1,2),"long release");});
scenario("S2-SHORT-EXACT-BOUNDARY",[](){GestureS2 g;GestureBatch b;g.accept(edge(3,1),10,b);b={};g.accept(edge(3,0),209,b);ok(find(b,GestureEventKind::Qualified,3,0),"199 short");GestureS2 h;GestureBatch c;h.accept(edge(3,1),10,c);c={};h.accept(edge(3,0),210,c);ok(find(c,GestureEventKind::Qualified,3,1)&&find(c,GestureEventKind::Qualified,3,2),"200 long then release");});
scenario("S2-COMBO-1-2-SAMPLE",[](){GestureS2 g;GestureBatch b;g.accept(edge(1,1),0,b);b={};g.accept(edge(2,1),89,b);ok(find(b,GestureEventKind::Qualified,4,3),"combo under90");b={};g.onTimer(289,b);ok(find(b,GestureEventKind::Qualified,4,1),"combo second LONG");b={};g.accept(edge(2,0),290,b);ok(find(b,GestureEventKind::Qualified,4,2),"second owns release");b={};g.accept(edge(1,0),291,b);ok(!find(b,GestureEventKind::Qualified,4,2),"first no double");});
scenario("S2-90-NO-COMBO",[](){GestureS2 g;GestureBatch b;g.accept(edge(1,1),0,b);b={};g.accept(edge(2,1),90,b);ok(!find(b,GestureEventKind::Qualified,4,3),"no combo 90ms");});
scenario("S2-COMBO-CATALOG",[](){const std::array<std::array<int,3>,6> pairs{{{{1,2,4}},{{1,3,6}},{{1,0,9}},{{2,1,5}},{{2,3,7}},{{2,0,8}}}};for(auto p:pairs){GestureS2 g;GestureBatch b;g.accept(edge(p[0],1),100,b);b={};g.accept(edge(p[1],1),120,b);ok(find(b,GestureEventKind::Qualified,p[2],3),"role mismatch");}});
scenario("S2-COMBO-SAME-TIME",[](){GestureS2 g;GestureBatch b;g.accept(edge(1,1),100,b);b={};g.accept(edge(2,1),100,b);ok(find(b,GestureEventKind::Qualified,4,3),"same-time ordered combo");});
scenario("S2-DJ2-ROT-BEFORE-RAW",[](){GestureS2 g;GestureBatch b;g.accept(edge(2,1),0,b);b={};g.accept(dj(21,70),199,b);ok(b.count==3&&b.items[0].kind==GestureEventKind::Qualified&&static_cast<int>(b.items[0].phase)==4&&b.items[1].role==10&&b.items[2].kind==GestureEventKind::RawDj,"DJ order");b={};g.accept(edge(2,0),201,b);ok(find(b,GestureEventKind::Qualified,10,2),"DJ release");});
scenario("S2-DJ2-ROT-AFTER-200",[](){GestureS2 g;GestureBatch b;g.accept(edge(2,1),0,b);b={};g.accept(dj(21,70),200,b);ok(!find(b,GestureEventKind::Qualified,10,3),"cannot combo at 200");ok(find(b,GestureEventKind::Qualified,2,1),"qualify long before DJ");});
scenario("S2-SHIFT-BEFORE-CC",[](){GestureS2 g;GestureBatch b;g.accept(edge(1,1),0,b);b={};g.accept(cc(4,80),90,b);ok(b.count==2&&b.items[0].kind==GestureEventKind::Qualified&&static_cast<int>(b.items[0].phase)==4&&b.items[1].kind==GestureEventKind::RawCc,"wrong CC order");});
scenario("S2-STOP-TRUE-UP",[](){GestureS2 g;GestureBatch b;g.accept(edge(1,1),0,b);b={};g.onTimer(210,b);g.onHostStop();b={};g.accept(edge(1,0),220,b);ok(find(b,GestureEventKind::Qualified,1,2)&&find(b,GestureEventKind::RawEdge,-1,0),"owed release missing");});
scenario("S2-STOP-PENDING",[](){GestureS2 g;GestureBatch b;g.accept(edge(1,1),0,b);g.onHostStop();b={};g.onTimer(250,b);ok(b.count==0,"no LONG after STOP");b={};g.accept(edge(1,0),251,b);ok(b.count==1&&b.items[0].kind==GestureEventKind::RawEdge,"only true UP raw");});
scenario("S2-RELOAD-HELD",[](){std::array<bool,36> held{};held[1]=true;GestureS2 g(held);GestureBatch b;g.accept(edge(1,0),201,b);ok(b.count==1&&b.items[0].kind==GestureEventKind::RawEdge,"no ghost action");});
scenario("S2-ORPHAN-UP",[](){GestureS2 g;GestureBatch b;g.accept(edge(3,0),1,b);ok(g.orphanUps()==1&&b.count==1&&b.items[0].kind==GestureEventKind::RawEdge,"orphan not forwarded");});
scenario("S2-NO-BACKDATED",[](){GestureS2 g;GestureBatch b;g.accept(edge(1,1),100,b);b={};ok(!g.onTimer(99,b),"backward time");ok(b.count==0&&g.held(1),"mutated backward");});
scenario("S4-REJECT-INVALID-INTENT",[](){OutputS4 x;x.setDiagnosticEnabled(true);ok(!x.apply({10,569,70,127}),"hole");ok(!x.apply({12,0,1,36}),"key");ok(!x.apply({11,0,2,127}),"binary");ok(!x.apply({15,572,22,127}),"special gap");ok(x.emitted()==0,"invalid emitted");});
scenario("S4-CONTINUOUS-DEDUP",[](){OutputS4 x;x.setDiagnosticEnabled(true);ok(x.apply({10,0,12,127}),"cc1");ok(x.apply({10,0,12,127}),"cc duplicate");ok(x.emitted()==1&&x.packet(0).status==182&&x.packet(0).number==0&&x.packet(0).value==12,"CC encoding");});
scenario("S4-CONTINUOUS-CHANNEL",[](){OutputS4 x;x.setDiagnosticEnabled(true);ok(x.apply({10,128,100,127}),"cc address128");ok(x.emitted()==1&&x.packet(0).status==183&&x.packet(0).number==0,"shifted channel from source");});
scenario("S4-TOUCH-RELEASE-OWNER",[](){OutputS4 x;x.setDiagnosticEnabled(true);ok(x.apply({12,3,1,6}),"touchon");ok(x.owner(6)==3&&x.debt(3),"owner set");ok(!x.apply({13,3,0,7}),"wrong owner" );ok(x.debt(3),"bad release mutated");ok(x.apply({13,3,0,6}),"release");ok(!x.debt(3)&&x.owner(6)==-1,"release debt");ok(x.emitted()==2&&x.packet(0).status==150&&x.packet(1).status==134,"on/off");});
scenario("S4-NOMINAL-OFF-DOESNT-STEAL-TOUCH",[](){OutputS4 x;x.setDiagnosticEnabled(true);x.apply({12,3,1,1});ok(x.apply({11,3,0,127}),"nominal off");ok(x.debt(3)&&x.emitted()==1,"stole touch");x.apply({13,3,0,1});ok(!x.debt(3)&&x.emitted()==2,"release wrong");});
scenario("S4-TOUCH-NOMINAL-RESTORE",[](){OutputS4 x;x.setDiagnosticEnabled(true);x.apply({11,3,1,127});x.apply({11,3,0,127});x.apply({12,3,1,1});x.apply({11,3,1,127});x.apply({13,3,0,1});ok(x.emitted()==5&&x.debt(3)&&x.packet(3).status==134&&x.packet(4).status==150,"nominal should resume after touch");});
scenario("S4-FLASH-ON-OFF",[](){OutputS4 x;x.setDiagnosticEnabled(true);ok(x.apply({14,12,1,8}),"flash");ok(x.emitted()==2&&x.packet(0).status==150&&x.packet(1).status==134&&!x.debt(12),"flash output");});
scenario("S4-STOP-CLOSE-DEBTS",[](){OutputS4 x;x.setDiagnosticEnabled(true);x.apply({12,4,1,1});x.apply({12,5,1,2});ok(x.onHostStop(),"STOP");ok(x.emitted()==4&&x.packet(2).number==4&&x.packet(3).number==5&&!x.debt(4)&&!x.debt(5),"STOP closure order");ok(!x.apply({13,4,0,1}),"ghost release accepted");});
scenario("S4-UNKNOWN-PROFILE-NO-INVENTED-OUT",[](){OutputS4 x;x.setDiagnosticEnabled(true);ok(x.apply({19,0,1,127}),"service diagnostic");ok(x.emitted()==0,"invented MIDI backend");});
scenario("PIPELINE-K2-TO-S2-NO-MUSIC",[](){CoreCoordinator c;ok(c.onMidi({14,0x90,13,127},0),"physical bot2");ok(c.onMidi({14,0x90,14,127},30),"physical bot3");bool combo=false;for(std::size_t i=0;i<c.traceCount();++i){const auto e=c.trace(i);if(e.kind==GestureEventKind::Qualified&&e.role==4&&static_cast<int>(e.phase)==3)combo=true;}ok(combo,"combo not wired");ok(c.output().emitted()==0&&c.originalStructuralPrototype().count()==0,"phantom music");});
scenario("PIPELINE-SHIFT-CC-EVENT-ORDER",[](){CoreCoordinator c;c.onMidi({14,0x90,13,127},0);c.drainTrace();ok(c.onMidi({14,0xB0,4,60},90),"CC");ok(c.traceCount()==2&&c.trace(0).kind==GestureEventKind::Qualified&&c.trace(1).kind==GestureEventKind::RawCc,"pipeline ordering");});
scenario("PIPELINE-STOP-NO-GHOST",[](){CoreCoordinator c;c.onMidi({14,0x90,13,127},0);c.onHostStop();c.drainTrace();c.onTimer(250);ok(c.traceCount()==0,"ghost timer");c.onMidi({14,0x80,13,0},251);ok(c.traceCount()==1&&c.trace(0).kind==GestureEventKind::RawEdge,"ghost release");});
scenario("PIPELINE-S4-EXPLICIT-ONLY",[](){CoreCoordinator c;c.onMidi({14,0x90,12,127},0);ok(c.output().emitted()==0,"physical bypassed authorisation");c.enableTestMidiProjection(true);ok(c.applyLogicalOutput({10,4,67,127}),"explicit intent");ok(c.output().emitted()==1&&c.output().packet(0).status==182&&c.output().packet(0).number==4,"explicit output");});
scenario("PIPELINE-KEEP-ENGINE-STRUCTURAL",[](){CoreCoordinator c;ok(c.testStructuralEvent({1,Kind::Down,0,60,127}),"structural down");ok(c.originalStructuralPrototype().count()==1&&c.output().emitted()==0,"shouldn't auto map structural to MIDI");});
scenario("S2-INVALID-NO-CLOCK-MUTATION",[](){GestureS2 g;GestureBatch b;g.accept(edge(1,1),100,b);b={};ok(!g.accept(edge(50,1),200,b),"invalid control");b={};ok(g.onTimer(190,b),"clock rejected after invalid frame");ok(find(b,GestureEventKind::Qualified,1,4),"SHIFT lost to invalid frame");});
scenario("S2-REJECT-FULL-BATCH-ATOMIC",[](){GestureS2 g;GestureBatch b;b.count=18;ok(!g.accept(edge(1,1),100,b),"full batch was accepted");ok(!g.held(1),"held committed under overflow");});
scenario("S4-FLASH-REJECT-LIVE-STATE",[](){OutputS4 x;x.setDiagnosticEnabled(true);x.apply({11,12,1,127});ok(!x.apply({14,12,1,1}),"flash should not duplicate ON state");ok(x.emitted()==1&&x.debt(12),"flash mutation");});
scenario("S4-FULL-STOP-BOUNDED",[](){OutputS4 x;x.setDiagnosticEnabled(true);for(int a=0;a<544;++a)ok(x.apply({11,a,1,127}),"nominal note fill");for(int a=544;a<608;++a)ok(x.apply({18,a,1,127}),"SOFT fill");ok(x.outstanding()==608&&x.emitted()==608,"fill state");ok(x.onHostStop(),"STOP overflow");ok(x.outstanding()==0&&x.emitted()==1216,"full debt close");ok(x.packet(608).status==134&&x.packet(608).number==0,"OFF order");});
scenario("S4-STOP-NO-REPLAY-AFTER-RESTART",[](){OutputS4 x;x.setDiagnosticEnabled(true);x.apply({12,0,1,0});x.onHostStop();x.drain();x.setDiagnosticEnabled(false);x.setDiagnosticEnabled(true);ok(x.emitted()==0&&!x.debt(0),"automatic replay on enable");});
scenario("PIPELINE-WRONG-CHANNEL-ISOLATION",[](){CoreCoordinator c;ok(!c.onMidi({15,0x90,13,127},0),"channel accepted");ok(!c.surface().held(1)&&c.traceCount()==0,"wrong channel state");ok(c.onMidi({14,0x90,13,127},0),"valid after rejected");});
scenario("PIPELINE-FULL-TRACE-REFUSAL",[](){CoreCoordinator c;for(int i=0;i<119;++i){ok(c.onMidi({14,0xB0,4,i%128},i),"fill trace");}ok(c.traceCount()==119,"trace fill");ok(!c.onMidi({14,0x90,13,127},119),"overflow accepted");ok(!c.surface().held(1),"surface mutated on refuse");});
std::cout<<"PASS "<<count<<" new S2/S4/pipeline scenarios\n";return 0;
}catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<"\n";return 1;}}
